// This single file holds several package-private classes for a runnable demo.
// In a real project each class lives in its own file.
package com.bank.catalog;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BankDemo {
    private static final Logger log = Logger.getLogger(BankDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountProduct rajeshProduct = new SavingsProduct("SAV2001", new BigDecimal("1000000"));
        AccountProduct priyaProduct  = new CurrentProduct("CUR3001", new BigDecimal("250000"));

        log.info(() -> "Rajesh product monthly charge: Rs." + monthlyCharge(rajeshProduct));
        log.info(() -> "Priya product monthly charge: Rs." + monthlyCharge(priyaProduct));

        log.info(() -> "Closed set of permitted products: " + ProductRegistry.permittedNames());

        // ── The following shapes DO NOT COMPILE — shown as comments to explain why ──
        //
        // 1. A sealed LOCAL class is forbidden — no stable name for a permits list:
        //      sealed class TempPromoProduct implements AccountProduct {}   // ERROR
        //
        // 2. A sealed ANONYMOUS class is forbidden — anonymous types have no name:
        //      AccountProduct p = new sealed AccountProduct() {};           // ERROR
        //
        // 3. A LAMBDA cannot implement a sealed interface — the compiler cannot
        //    synthesize an implementor of a closed type:
        //      AccountProduct p = () -> {};                                 // ERROR
        //
        // The ONLY legal implementors are the named ones in the permits clause.
    }

    // exhaustive switch over the closed set — no default needed
    static BigDecimal monthlyCharge(AccountProduct product) {
        return switch (product) {
            case SavingsProduct s      -> BigDecimal.ZERO;
            case CurrentProduct c      -> new BigDecimal("500");
            case FixedDepositProduct f -> BigDecimal.ZERO;
        };
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
