package com.bank.catalog;

// Sealed interface: the closed set of account products is named and fixed.
// Local and anonymous classes CANNOT appear here because they have no stable name.
public sealed interface AccountProduct
        permits SavingsProduct, CurrentProduct, FixedDepositProduct {
    String accountId();
}
