package com.bank.catalog;

import java.util.Arrays;
import java.util.List;

// Enumerates the closed set straight from the sealed permits list.
public final class ProductRegistry {
    private ProductRegistry() { }

    public static List<String> permittedNames() {
        return Arrays.stream(AccountProduct.class.getPermittedSubclasses())
                .map(Class::getSimpleName)
                .toList();
    }
}
